/*
 * A040794  Continued fraction for sqrt(823).
 * https://oeis.org/A040794
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy
 * Formula:   compute the nth coefficient of the continued fraction expansion
 *            of sqrt(823) (OEIS A040794). The coefficients are generated by
 *            the standard algorithm: a_0 = floor(sqrt(823)), m_0 = 0, d_0 =
 *            1; for k ≥ 1: m_k = d_{k-1}*a_{k-1} - m_{k-1}; d_k = (823 -
 *            m_k*m_k) / d_{k-1}; a_k = floor( (a_0 + m_k) /...
 * Range:     u8 n <= 89, u16 n <= 89, u32 n <= 89, u64 n <= 89, u128 n <= 89,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* seq_t and idx_t are supplied by the build */
#include <stdint.h>

seq_t a(idx_t n)
{
    const uint64_t D = 823;
    const uint64_t a0 = 28;        /* floor(sqrt(823)) */
    uint64_t m = 0;
    uint64_t d = 1;
    if (n == 0) {
        return (seq_t)a0;
    }
    uint64_t ak = a0;
    for (idx_t i = 1; i <= n; ++i) {
        m = d * ak - m;
        d = (D - m * m) / d;
        ak = (a0 + m) / d;
    }
    return (seq_t)ak;
}
